CREATE TABLE product_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE brands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,document VARCHAR(30) NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,address VARCHAR(255) NULL,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,document VARCHAR(30) NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,address VARCHAR(255) NULL,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,species VARCHAR(60) NOT NULL,breed VARCHAR(80) NULL,sex VARCHAR(30) NULL,birth_date DATE NULL,weight DECIMAL(10,3) NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(client_id) REFERENCES clients(id),CHECK(weight IS NULL OR weight>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE specialties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE veterinarians (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,specialty_id BIGINT UNSIGNED NULL,license_number VARCHAR(60) NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(specialty_id) REFERENCES specialties(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT NULL,specialty_id BIGINT UNSIGNED NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,duration_minutes INT NOT NULL DEFAULT 30,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(specialty_id) REFERENCES specialties(id),CHECK(price>=0),CHECK(duration_minutes BETWEEN 5 AND 480)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,barcode VARCHAR(80) NULL UNIQUE,name VARCHAR(160) NOT NULL,description TEXT NULL,category_id BIGINT UNSIGNED NULL,brand_id BIGINT UNSIGNED NULL,presentation VARCHAR(120) NULL,unit VARCHAR(20) NOT NULL DEFAULT 'unidad',price DECIMAL(12,2) NOT NULL DEFAULT 0,min_stock DECIMAL(14,3) NOT NULL DEFAULT 0,publish_online BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(category_id) REFERENCES product_categories(id),FOREIGN KEY(brand_id) REFERENCES brands(id),CHECK(price>=0),CHECK(min_stock>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO role_permissions(role_id,permission) SELECT id,'catalogs.read' FROM roles WHERE name IN ('Recepcionista','Cajero','Veterinario');
INSERT INTO role_permissions(role_id,permission) SELECT id,'catalogs.write' FROM roles WHERE name='Recepcionista';
